'use strict';
const CACHE='murim-v03-release-1';
const FILES=['./','index.html','style.css','profile.js','sound.js','world.js','bosses.js','enemies.js','combat.js','game.js','camp.js','controls.js','app.js','manifest.webmanifest','icon-192.png','icon-512.png'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(async cache=>{for(const file of FILES){const request=new Request(new URL(file,self.registration.scope),{cache:'reload'}),response=await fetch(request);if(!response.ok||response.redirected||response.type==='opaque')throw new Error('Unable to cache game asset');await cache.put(request,response)}}));self.skipWaiting()});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('murim-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!url.href.startsWith(self.registration.scope))return;if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(()=>caches.match(new URL('./',self.registration.scope))));return}if(FILES.some(path=>new URL(path,self.registration.scope).pathname===url.pathname))event.respondWith(caches.match(event.request).then(hit=>hit||fetch(event.request)))});
